+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.textfield.TextFieldBase;
+import com.vaadin.flow.data.validator.EmailValidator;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveEvent.ContinueNavigationAction;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final int MAX_MESSAGE_LENGTH = 500;
+    private static final Pattern EMAIL = Pattern.compile(EmailValidator.PATTERN);
+
+    private final ContactMessageService messages;
+
+    private final TextField nameField = new TextField("Name");
+    private final EmailField emailField = new EmailField("Email");
+    private final TextField phoneField = new TextField("Phone");
+    private final TextArea messageField = new TextArea("Message");
+    private final Button sendButton = new Button("Send", e -> submit());
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    /** Set while the form is cleared after a send, so that clearing does not re-enable Send. */
+    private boolean clearingForm;
+
+    public ContactView(ContactMessageService messages) {
+        this.messages = messages;
+
+        // Validation runs only on Send, so the browser must not change the invalid state on its own.
+        for (TextFieldBase<?, String> input : List.of(nameField, emailField, phoneField, messageField)) {
+            input.setManualValidation(true);
+            // Sync every keystroke, so that Enter sends what is on screen.
+            input.setValueChangeMode(ValueChangeMode.EAGER);
+        }
+        nameField.addValueChangeListener(e -> enableSendAfterEdit());
+        emailField.addValueChangeListener(e -> enableSendAfterEdit());
+        phoneField.addValueChangeListener(e -> enableSendAfterEdit());
+        messageField.addValueChangeListener(e -> enableSendAfterEdit());
+
+        // Enter sends from anywhere on the page, except the About link and the grid (see stopEnterFrom).
+        // Shift+Enter still gives a line break in the message.
+        Shortcuts.addShortcutListener(this, this::submit, Key.ENTER);
+
+        var form = new FormLayout(nameField, emailField, phoneField, messageField);
+        form.setResponsiveSteps(new FormLayout.ResponsiveStep("0", 1), new FormLayout.ResponsiveStep("40em", 2));
+        form.setColspan(messageField, 2);
+
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::email).setHeader("Email");
+        grid.addColumn(ContactMessage::phone).setHeader("Phone");
+        grid.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        refreshGrid();
+
+        var aboutLink = new RouterLink("About", AboutView.class);
+        stopEnterFrom(aboutLink);
+        stopEnterFrom(grid);
+        add(new H1("Contact"), aboutLink, form, sendButton, new H2("Sent messages"), grid);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasInput()) {
+            confirmLeaving(event.postpone());
+        }
+    }
+
+    private void submit() {
+        if (!sendButton.isEnabled() || !validate()) {
+            return;
+        }
+        messages.save(new ContactMessage(
+                nameField.getValue().strip(),
+                emailField.getValue().strip(),
+                phoneField.getValue().strip(),
+                messageField.getValue().strip()));
+        refreshGrid();
+        Notification.show("Message sent");
+        clearForm();
+        sendButton.setEnabled(false);
+    }
+
+    /**
+     * Marks every field that breaks a rule, and clears the mark on the others.
+     *
+     * @return true if the form is valid
+     */
+    private boolean validate() {
+        String name = nameField.getValue().strip();
+        String email = emailField.getValue().strip();
+        String phone = phoneField.getValue().strip();
+        String message = messageField.getValue().strip();
+
+        String nameError = name.isEmpty() ? "Name is required" : null;
+        String emailError = emailError(email, phone);
+        String messageError = messageError(message);
+
+        showError(nameField, nameError);
+        showError(emailField, emailError);
+        showError(messageField, messageError);
+        return nameError == null && emailError == null && messageError == null;
+    }
+
+    private static String emailError(String email, String phone) {
+        if (!email.isEmpty()) {
+            return EMAIL.matcher(email).matches() ? null : "Enter a valid e-mail address";
+        }
+        return phone.isEmpty() ? "Give an e-mail address or a phone number" : null;
+    }
+
+    private static String messageError(String message) {
+        if (message.isEmpty()) {
+            return "Message is required";
+        }
+        if (message.codePointCount(0, message.length()) > MAX_MESSAGE_LENGTH) {
+            return "Message must be at most " + MAX_MESSAGE_LENGTH + " characters";
+        }
+        return null;
+    }
+
+    private static void showError(HasValidation field, String error) {
+        field.setErrorMessage(error);
+        field.setInvalid(error != null);
+    }
+
+    /** Keeps Enter pressed on the component from reaching the page-wide Enter shortcut. */
+    private static void stopEnterFrom(Component component) {
+        component.getElement().addEventListener("keydown", e -> { })
+                .setFilter("event.key === 'Enter'")
+                .stopPropagation();
+    }
+
+    private void enableSendAfterEdit() {
+        if (!clearingForm) {
+            sendButton.setEnabled(true);
+        }
+    }
+
+    private void clearForm() {
+        clearingForm = true;
+        try {
+            nameField.clear();
+            emailField.clear();
+            phoneField.clear();
+            messageField.clear();
+        } finally {
+            clearingForm = false;
+        }
+    }
+
+    private boolean hasInput() {
+        return !nameField.isEmpty() || !emailField.isEmpty() || !phoneField.isEmpty() || !messageField.isEmpty();
+    }
+
+    private void refreshGrid() {
+        grid.setItems(messages.findAllNewestFirst());
+    }
+
+    private void confirmLeaving(ContinueNavigationAction navigation) {
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Discard your message?");
+        dialog.add(new Paragraph("What you have typed will be lost if you leave this page."));
+
+        Button keepEditing = new Button("Keep editing", e -> dialog.close());
+        Button discard = new Button("Discard", e -> {
+            dialog.close();
+            navigation.proceed();
+        });
+        dialog.getFooter().add(keepEditing, discard);
+
+        dialog.addOpenedChangeListener(e -> {
+            if (!e.isOpened()) {
+                remove(dialog);
+            }
+        });
+        add(dialog);
+        dialog.open();
+    }
+}
