+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Override
+    public String getView() {
+        return "contact";
+    }
+
+    @Test
+    void emptySendShowsErrorsInTheBrowser() {
+        ButtonElement.getByText(page, "Send").click();
+
+        TextFieldElement.getByLabel(page, "Name").assertErrorMessage("Name is required");
+        EmailFieldElement.getByLabel(page, "Email").assertErrorMessage("Give an e-mail address or a phone number");
+        TextAreaElement.getByLabel(page, "Message").assertErrorMessage("Message is required");
+        assertThat(page.getByText("Message sent")).hasCount(0);
+    }
+
+    @Test
+    void enterSendsWhatIsOnScreenRightAfterTyping() {
+        String name = unique("enter");
+        TextFieldElement.getByLabel(page, "Name").getFocusLocator().fill(name);
+        TextFieldElement.getByLabel(page, "Phone").getFocusLocator().fill("555 0100");
+        TextAreaElement message = TextAreaElement.getByLabel(page, "Message");
+        message.getInputLocator().fill("Sent with Enter");
+        message.getInputLocator().press("Enter");
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        assertThat(page.locator("vaadin-grid").getByText(name)).isVisible();
+        assertThat(TextFieldElement.getByLabel(page, "Name").getFocusLocator()).hasValue("");
+        ButtonElement.getByText(page, "Send").assertDisabled();
+    }
+
+    @Test
+    void sendButtonIsEnabledAgainAfterAnEdit() {
+        TextFieldElement.getByLabel(page, "Name").getFocusLocator().fill(unique("edit"));
+        TextFieldElement.getByLabel(page, "Phone").getFocusLocator().fill("555 0100");
+        TextAreaElement.getByLabel(page, "Message").getInputLocator().fill("Hi");
+        ButtonElement.getByText(page, "Send").click();
+        ButtonElement.getByText(page, "Send").assertDisabled();
+
+        TextAreaElement.getByLabel(page, "Message").getInputLocator().fill("Hi again");
+
+        ButtonElement.getByText(page, "Send").assertEnabled();
+    }
+
+    @Test
+    void shiftEnterKeepsTypingInTheMessage() {
+        TextAreaElement message = TextAreaElement.getByLabel(page, "Message");
+        message.getInputLocator().fill("line one");
+        message.getInputLocator().press("Shift+Enter");
+        message.getInputLocator().pressSequentially("line two");
+
+        assertThat(message.getInputLocator()).hasValue("line one\nline two");
+        assertThat(page.getByText("Message sent")).hasCount(0);
+    }
+
+    @Test
+    void leavingWithTypedTextAsksFirstAndKeepEditingStays() {
+        TextFieldElement.getByLabel(page, "Name").getFocusLocator().fill("Eve");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+        DialogElement dialog = DialogElement.getByHeaderText(page, "Discard your message?");
+        dialog.assertOpen();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+
+        dialog.assertClosed();
+        assertThat(page).hasURL(Pattern.compile(".*/contact$"));
+        assertThat(TextFieldElement.getByLabel(page, "Name").getFocusLocator()).hasValue("Eve");
+    }
+
+    @Test
+    void discardGoesToAboutView() {
+        TextFieldElement.getByLabel(page, "Name").getFocusLocator().fill("Frank");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+        DialogElement.getByHeaderText(page, "Discard your message?").assertOpen();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard")).click();
+
+        assertThat(page).hasURL(Pattern.compile(".*/about$"));
+        assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About"))).isVisible();
+    }
+
+    @Test
+    void enterWhileTheLeaveDialogIsOpenDoesNotSubmit() {
+        TextFieldElement.getByLabel(page, "Name").getFocusLocator().fill("Hank");
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+        DialogElement.getByHeaderText(page, "Discard your message?").assertOpen();
+
+        page.keyboard().press("Enter");
+
+        TextAreaElement.getByLabel(page, "Message").assertValid();
+        assertThat(page.getByText("Message sent")).hasCount(0);
+    }
+
+    @Test
+    void browserBackWithTypedTextAsksFirst() {
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+        assertThat(page).hasURL(Pattern.compile(".*/about$"));
+        page.goBack();
+        assertThat(page).hasURL(Pattern.compile(".*/contact$"));
+        TextFieldElement.getByLabel(page, "Name").getFocusLocator().fill("Ivy");
+
+        page.goForward();
+
+        DialogElement dialog = DialogElement.getByHeaderText(page, "Discard your message?");
+        dialog.assertOpen();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+        dialog.assertClosed();
+        assertThat(TextFieldElement.getByLabel(page, "Name").getFocusLocator()).hasValue("Ivy");
+        assertThat(page).hasURL(Pattern.compile(".*/contact$"));
+    }
+
+    @Test
+    void enterOnTheFocusedAboutLinkStillFollowsTheLink() {
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).focus();
+        page.keyboard().press("Enter");
+
+        assertThat(page).hasURL(Pattern.compile(".*/about$"));
+    }
+
+    @Test
+    void enterOnTheFocusedAboutLinkDoesNotSendAValidForm() {
+        TextFieldElement.getByLabel(page, "Name").getFocusLocator().fill(unique("link-send"));
+        TextFieldElement.getByLabel(page, "Phone").getFocusLocator().fill("555 0100");
+        TextAreaElement.getByLabel(page, "Message").getInputLocator().fill("Hi");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).focus();
+        page.keyboard().press("Enter");
+
+        DialogElement.getByHeaderText(page, "Discard your message?").assertOpen();
+        assertThat(page.getByText("Message sent")).hasCount(0);
+    }
+
+    @Test
+    void enterInTheGridDoesNotSendAValidForm() {
+        TextFieldElement.getByLabel(page, "Name").getFocusLocator().fill(unique("grid-send"));
+        TextFieldElement.getByLabel(page, "Phone").getFocusLocator().fill("555 0100");
+        TextAreaElement.getByLabel(page, "Message").getInputLocator().fill("Hi");
+
+        page.keyboard().press("Tab");
+        page.keyboard().press("Tab");
+        assertEquals("VAADIN-GRID", page.evaluate("() => document.activeElement.localName.toUpperCase()"));
+        page.keyboard().press("Enter");
+
+        assertThat(page.getByText("Message sent")).hasCount(0);
+        assertThat(TextFieldElement.getByLabel(page, "Name").getFocusLocator()).hasValue(Pattern.compile("^grid-send-.*"));
+    }
+
+    @Test
+    void leavingWithEmptyFormIsNotInterrupted() {
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+
+        assertThat(page).hasURL(Pattern.compile(".*/about$"));
+        assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About"))).isVisible();
+        assertThat(page.getByRole(AriaRole.DIALOG)).hasCount(0);
+    }
+
+    private static String unique(String prefix) {
+        return prefix + "-" + UUID.randomUUID();
+    }
+}
