+
+    @Test
+    void emailOnlyIsEnoughWithoutPhone() {
+        navigate(ContactView.class);
+        String name = unique("email-only");
+
+        test(name()).setValue(name);
+        test(email()).setValue("alice@example.com");
+        test(message()).setValue("Hello");
+        test(send()).click();
+
+        assertFirstRowName(name);
+        assertFalse(email().isInvalid());
+        assertEquals("", email().getValue());
+    }
+
+    @Test
+    void phoneOnlyIsEnoughWithoutEmail() {
+        navigate(ContactView.class);
+        String name = unique("phone-only");
+
+        test(name()).setValue(name);
+        test(phone()).setValue("+358 40 123 4567");
+        test(message()).setValue("Hello");
