+
+        test(name()).setValue("Bob");
+        test(email()).setValue("bob@");
+        test(send()).click();
+
+        assertEquals("Bob", name().getValue());
+        assertEquals("bob@", email().getValue());
+        assertFalse($(Notification.class).exists());
+    }
+
+    @Test
+    void validSendNotifiesListsAndClearsTheForm() {
+        navigate(ContactView.class);
+        String name = unique("sent");
+
+        test(name()).setValue(name);
+        test(email()).setValue("sent@example.com");
+        test(phone()).setValue("123");
+        test(message()).setValue("Hello there");
