+
+    @Test
+    void enterOnInvalidFormSendsNothing() {
+        navigate(ContactView.class);
+
+        fireShortcut(Key.ENTER);
+
+        assertTrue(name().isInvalid());
+        assertFalse($(Notification.class).exists());
+    }
+
+    @Test
+    void enterDoesNotResendWhileSendIsDisabled() {
+        navigate(ContactView.class);
+        String name = unique("no-resend");
+
+        test(name()).setValue(name);
+        test(phone()).setValue("123");
+        test(message()).setValue("Once");
+        test(send()).click();
+        int messagesBefore = messagesInGrid().size();
+        int notificationsBefore = $(Notification.class).all().size();
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals(messagesBefore, messagesInGrid().size());
+        assertEquals(notificationsBefore, $(Notification.class).all().size());
+    }
+
+    @Test
+    void listedMessagesAreNewestFirstAndSurviveRevisiting() {
+        navigate(ContactView.class);
+        String older = unique("older");
+        String newer = unique("newer");
+
+        test(name()).setValue(older);
+        test(phone()).setValue("123");
+        test(message()).setValue("First");
+        test(send()).click();
+        test(name()).setValue(newer);
+        test(phone()).setValue("123");
+        test(message()).setValue("Second");
+        test(send()).click();
+
+        navigate(ContactView.class);
+
+        List<ContactMessage> items = messagesInGrid();
+        assertEquals(newer, items.get(0).name());
+        assertEquals(older, items.get(1).name());
+    }
+
+    @Test
+    void aboutLinkNavigatesToAboutView() {
+        navigate(ContactView.class);
+
